// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro, QuestaoDaAvaliacao } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"A escola e o seu território","html":"<p>A escola faz parte de um bairro, com suas relações, seus conflitos e, em alguns lugares, com a presença de grupos armados. Esses fatores entram na rotina da escola mesmo quando ninguém fala sobre eles.</p><p>Este guia trata de três frentes: os conflitos com famílias, a relação com a comunidade e a conduta diante da violência armada no entorno. Em todas, vale a mesma regra: a vida e a proteção das pessoas vêm antes de qualquer outra decisão.</p><h3>Ao final, você será capaz de</h3><ul><li>Conduzir uma conversa difícil com um responsável.</li><li>Acionar a rede de proteção no caso certo e pelo caminho certo.</li><li>Preparar a escola para uma situação de violência no entorno.</li><li>Agir com segurança durante e depois de uma crise.</li><li>Apoiar alunos afetados sem expor nem rotular.</li><li>Cuidar da equipe.</li></ul><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>O que significa</th></tr></thead><tbody><tr><td data-rotulo=\"Princípio\">Proteção da vida</td><td data-rotulo=\"O que significa\">Nenhuma atividade, prova ou meta vale o risco à vida de alunos e servidores.</td></tr><tr><td data-rotulo=\"Princípio\">Neutralidade</td><td data-rotulo=\"O que significa\">A escola atende a todos e não toma partido em disputas do território.</td></tr><tr><td data-rotulo=\"Princípio\">Papel da escola</td><td data-rotulo=\"O que significa\">A escola educa e protege. Não investiga, não julga e não substitui a polícia nem a assistência social.</td></tr><tr><td data-rotulo=\"Princípio\">Sigilo</td><td data-rotulo=\"O que significa\">Informações sobre alunos e famílias são tratadas com reserva.</td></tr><tr><td data-rotulo=\"Princípio\">Trabalho em rede</td><td data-rotulo=\"O que significa\">Nenhuma escola resolve sozinha. A direção aciona a Secretaria e os serviços de proteção.</td></tr></tbody></table></div>"},{"id":"c2","titulo":"Conflitos com famílias","html":"<p>A maior parte dos conflitos com responsáveis nasce de falta de informação, de uma decisão não explicada ou de uma preocupação que não foi ouvida.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Acolher</b><small>receber em local reservado</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Ouvir</b><small>sem interromper nem se defender</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Entender</b><small>resumir o que foi dito</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Combinar</b><small>o que a escola fará e em que prazo</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Dar retorno</b><small>na data combinada</small></div></div><figcaption>Figura. Os passos de uma conversa difícil com um responsável.</figcaption></figure><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>Como conduzir</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Responsável chega exaltado</td><td data-rotulo=\"Como conduzir\">Levar a um local reservado, com duas pessoas da escola. Falar baixo e devagar. Não discutir no portão nem diante de alunos.</td></tr><tr><td data-rotulo=\"Situação\">Queixa sobre um professor</td><td data-rotulo=\"Como conduzir\">Ouvir, registrar os fatos e dizer que a escola vai ouvir o professor. Não dar razão a nenhum dos lados antes disso.</td></tr><tr><td data-rotulo=\"Situação\">Briga entre alunos envolve as famílias</td><td data-rotulo=\"Como conduzir\">Atender cada família em separado. Tratar dos fatos e do que a escola fará, sem comparar os alunos.</td></tr><tr><td data-rotulo=\"Situação\">Responsável ameaça um servidor</td><td data-rotulo=\"Como conduzir\">Encerrar o atendimento, registrar o ocorrido, comunicar à Secretaria e, havendo risco, acionar a polícia.</td></tr><tr><td data-rotulo=\"Situação\">Família não comparece</td><td data-rotulo=\"Como conduzir\">Tentar outros horários e meios. Persistindo a ausência com prejuízo ao aluno, comunicar ao Conselho Tutelar.</td></tr></tbody></table></div><div class=\"nota\"><b>Registro</b><br/>Todo atendimento de conflito é registrado no mesmo dia: data, quem participou, o que foi relatado e o que foi combinado. O registro protege o aluno, a família e o servidor.</div>"},{"id":"c3","titulo":"Mediação de conflitos na escola","html":"<p>Em conflitos entre alunos, ou entre aluno e professor, a mediação busca reparar a relação e evitar que o problema volte. Ela não substitui as providências previstas no regimento quando há violência.</p><ol class=\"passos\"><li>Ouça cada parte em separado.</li><li>Verifique se as duas aceitam conversar.</li><li>Reúna as partes, com regras claras: um fala por vez, sem ofensas.</li><li>Peça que cada um diga o que aconteceu e como se sentiu.</li><li>Construa um combinado concreto, com o que cada um fará.</li><li>Acompanhe nos dias seguintes.</li></ol><div class=\"nota alerta\"><b>Quando não mediar</b><br/>Não se faz mediação em casos de violência sexual, ameaça grave, agressão com lesão ou quando uma das partes tem medo da outra. Nesses casos, a escola protege a vítima e aciona a rede de proteção.</div>"},{"id":"c4","titulo":"A rede de proteção","html":"<p>A escola é uma das portas da rede de proteção da criança e do adolescente. Conhecer os serviços e ter os contatos à mão antes de precisar é parte do trabalho da gestão.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Serviço</th><th>Quando acionar</th><th>Como</th></tr></thead><tbody><tr><td data-rotulo=\"Serviço\">Conselho Tutelar</td><td data-rotulo=\"Quando acionar\">Suspeita ou confirmação de violência, negligência ou violação de direitos de criança ou adolescente.</td><td data-rotulo=\"Como\">Comunicação pela direção da escola. É obrigatória.</td></tr><tr><td data-rotulo=\"Serviço\">Disque 100</td><td data-rotulo=\"Quando acionar\">Denúncia de violação de direitos humanos, inclusive anônima.</td><td data-rotulo=\"Como\">Telefone 100, todos os dias, 24 horas.</td></tr><tr><td data-rotulo=\"Serviço\">Polícia Militar</td><td data-rotulo=\"Quando acionar\">Risco imediato à vida ou crime em andamento.</td><td data-rotulo=\"Como\">Telefone 190.</td></tr><tr><td data-rotulo=\"Serviço\">SAMU</td><td data-rotulo=\"Quando acionar\">Pessoa ferida ou em emergência de saúde.</td><td data-rotulo=\"Como\">Telefone 192.</td></tr><tr><td data-rotulo=\"Serviço\">CRAS e CREAS</td><td data-rotulo=\"Quando acionar\">Família em vulnerabilidade ou com direitos violados.</td><td data-rotulo=\"Como\">Encaminhamento pela direção ou pelo Conselho Tutelar.</td></tr><tr><td data-rotulo=\"Serviço\">Unidade de saúde e CAPS</td><td data-rotulo=\"Quando acionar\">Sofrimento emocional, uso de substâncias ou suspeita de transtorno.</td><td data-rotulo=\"Como\">Encaminhamento pela escola, com a família.</td></tr><tr><td data-rotulo=\"Serviço\">Ministério Público e Defensoria Pública</td><td data-rotulo=\"Quando acionar\">Violação de direitos sem resposta dos demais serviços.</td><td data-rotulo=\"Como\">Pela Secretaria de Educação ou pela direção.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Comunicação obrigatória</b><br/>O Estatuto da Criança e do Adolescente obriga a comunicar ao Conselho Tutelar os casos de suspeita ou confirmação de maus-tratos (art. 13). Deixar de comunicar é infração para o professor e para o responsável pela escola (art. 245). A escola comunica a suspeita. Não precisa provar.</div>"},{"id":"c5","titulo":"Quando o território afeta a rotina da escola","html":"<p>Em áreas com presença de grupos armados, a escola pode enfrentar disparos no entorno, toques de recolher, ameaças e pressão sobre alunos e famílias. A gestão não controla esses fatores, mas pode preparar a escola para reduzir os riscos.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Sinal no território</th><th>O que observar</th><th>O que fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Sinal no território\">Movimentação incomum</td><td data-rotulo=\"O que observar\">Comércio fechando, ruas vazias, alunos sendo buscados mais cedo.</td><td data-rotulo=\"O que fazer\">Confirmar com parceiros do território e avisar a Secretaria.</td></tr><tr><td data-rotulo=\"Sinal no território\">Queda brusca de frequência</td><td data-rotulo=\"O que observar\">Muitas faltas em um mesmo dia ou de uma mesma região.</td><td data-rotulo=\"O que fazer\">Procurar entender o motivo antes de cobrar presença.</td></tr><tr><td data-rotulo=\"Sinal no território\">Pressão sobre a escola</td><td data-rotulo=\"O que observar\">Pedidos para fechar, mudar horário ou liberar o espaço.</td><td data-rotulo=\"O que fazer\">Não negociar sozinho. Comunicar imediatamente à Secretaria.</td></tr><tr><td data-rotulo=\"Sinal no território\">Alunos com medo de ir ou de voltar</td><td data-rotulo=\"O que observar\">Relatos de trajeto perigoso.</td><td data-rotulo=\"O que fazer\">Registrar e levar à Secretaria e ao Conselho Tutelar.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>O que a escola não faz</b><br/>A escola não confronta, não investiga, não repassa informações sobre pessoas do território e não faz acordos. Qualquer contato de grupos armados com a escola é comunicado à Secretaria no mesmo dia.</div>"},{"id":"c6","titulo":"Como preparar a escola","html":"<p>A preparação segue os eixos da metodologia Acesso Mais Seguro, do Comitê Internacional da Cruz Vermelha, usada por redes públicas no Brasil: conhecer o contexto, tratar os riscos, gerir a crise e cuidar da equipe.</p><figure><div class=\"ciclo\"><div class=\"q\"><span class=\"n\">1</span><b>Conhecer</b><small>Mapear os riscos do entorno e os horários mais sensíveis.</small></div><div class=\"q\"><span class=\"n\">2</span><b>Preparar</b><small>Definir locais mais seguros, rotas, sinais de alerta e quem decide.</small></div><div class=\"q\"><span class=\"n\">3</span><b>Agir</b><small>Seguir o combinado durante a crise.</small></div><div class=\"q\"><span class=\"n\">4</span><b>Cuidar</b><small>Acolher alunos e equipe e rever o plano.</small></div><div class=\"volta\">volta ao passo 1 na semana seguinte</div></div><figcaption>Figura. O ciclo de preparação da escola.</figcaption></figure><ul class=\"chk\"><li><span></span>A escola definiu o local mais seguro de cada bloco, longe de janelas e de paredes voltadas para a rua.</li><li><span></span>Todos os servidores conhecem o sinal combinado e sabem o que fazer com a turma.</li><li><span></span>Há uma pessoa responsável por decidir e uma substituta, em cada turno.</li><li><span></span>A lista de telefones da Secretaria, da rede de proteção e dos responsáveis está atualizada e impressa.</li><li><span></span>A escola combinou com a Secretaria quem decide sobre suspensão de aulas e liberação de alunos.</li><li><span></span>Os responsáveis foram informados de como a escola age e de que os alunos não são liberados durante o risco.</li><li><span></span>Novos servidores recebem a orientação ao chegar.</li></ul>"},{"id":"c7","titulo":"Durante e depois de uma crise","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Momento</th><th>O que fazer</th><th>O que evitar</th></tr></thead><tbody><tr><td data-rotulo=\"Momento\">Antes</td><td data-rotulo=\"O que fazer\">Conhecer o território e os sinais de alerta. Definir o local mais seguro da escola, as rotas e os pontos de encontro. Manter a lista de telefones atualizada.</td><td data-rotulo=\"O que evitar\">Rotas perigosas, mesmo que mais curtas. Deslocar-se sozinho em área de risco.</td></tr><tr><td data-rotulo=\"Momento\">Durante disparos</td><td data-rotulo=\"O que fazer\">Deitar-se e orientar os alunos a deitar. Afastar todos de janelas e portas. Levar o grupo, abaixado, ao local mais seguro e permanecer lá.</td><td data-rotulo=\"O que evitar\">Olhar pela janela. Filmar ou fotografar. Usar o telefone antes de estar protegido. Liberar os alunos.</td></tr><tr><td data-rotulo=\"Momento\">Depois</td><td data-rotulo=\"O que fazer\">Esperar algum tempo, pois pode haver novos disparos. Confirmar com parceiros do território que a situação normalizou. Avisar a equipe e a Secretaria.</td><td data-rotulo=\"O que evitar\">Sair logo após os disparos. Tocar em armas ou munições. Compartilhar imagens.</td></tr></tbody></table></div><h3>Decisões da direção</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Decisão</th><th>Critério</th></tr></thead><tbody><tr><td data-rotulo=\"Decisão\">Manter os alunos na escola</td><td data-rotulo=\"Critério\">Enquanto houver risco no entorno, a escola é mais segura do que a rua.</td></tr><tr><td data-rotulo=\"Decisão\">Liberar os alunos</td><td data-rotulo=\"Critério\">Somente após confirmar que a situação normalizou e, se possível, com entrega aos responsáveis.</td></tr><tr><td data-rotulo=\"Decisão\">Suspender as aulas</td><td data-rotulo=\"Critério\">Decisão tomada com a Secretaria, com base nas informações do território.</td></tr><tr><td data-rotulo=\"Decisão\">Comunicar os responsáveis</td><td data-rotulo=\"Critério\">Mensagem curta, pelos canais da escola: os alunos estão protegidos, não venham buscar agora, a escola avisará.</td></tr></tbody></table></div><h3>Depois</h3><ul><li>Verifique se há feridos e acione o SAMU.</li><li>Reúna a equipe, ainda no mesmo dia, para ouvir e orientar.</li><li>Registre o ocorrido e comunique à Secretaria.</li><li>No retorno às aulas, reserve tempo para os alunos falarem, sem obrigar ninguém.</li><li>Reveja o plano: o que funcionou e o que precisa mudar.</li></ul>"},{"id":"c8","titulo":"Alunos e famílias afetados","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>Conduta da gestão</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Aluno com familiar preso, morto ou envolvido com grupos armados</td><td data-rotulo=\"Conduta da gestão\">Acolher sem perguntar detalhes. Garantir que não seja rotulado. Acionar o apoio psicossocial da rede.</td></tr><tr><td data-rotulo=\"Situação\">Aluno que perdeu colega ou parente pela violência</td><td data-rotulo=\"Conduta da gestão\">Avisar os professores com discrição. Flexibilizar prazos. Encaminhar à unidade de saúde.</td></tr><tr><td data-rotulo=\"Situação\">Família ameaçada ou que precisa sair do bairro</td><td data-rotulo=\"Conduta da gestão\">Facilitar a transferência com sigilo. Não divulgar o destino.</td></tr><tr><td data-rotulo=\"Situação\">Suspeita de que um aluno está sendo aliciado</td><td data-rotulo=\"Conduta da gestão\">Não confrontar o aluno nem terceiros. Comunicar ao Conselho Tutelar e à Secretaria. Reforçar o vínculo com a escola.</td></tr><tr><td data-rotulo=\"Situação\">Aluno que traz arma ou objeto ilícito</td><td data-rotulo=\"Conduta da gestão\">Não revistar nem enfrentar. Afastar os demais, manter a calma e seguir o protocolo da Secretaria.</td></tr></tbody></table></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a turma que parou de vir</div><p><b>Situação.</b> Em uma semana, metade dos alunos de uma região do bairro falta todos os dias. Ninguém explica o motivo.</p><p><b>O que fazer.</b></p><ol><li>Converse com responsáveis de confiança, em separado, para entender o que ocorre.</li><li>Não cobre presença nem registre a falta como desinteresse.</li><li>Comunique à Secretaria e, se houver risco no trajeto, ao Conselho Tutelar.</li><li>Ofereça atividades para casa e o reforço escolar enquanto durar a situação.</li><li>Quando os alunos voltarem, acolha sem interrogar.</li></ol><p><b>Resultado esperado.</b> Os alunos mantêm o vínculo com a escola, e a rede de proteção passa a acompanhar o caso.</p></div>"},{"id":"c9","titulo":"Cuidado com a equipe","html":"<p>Trabalhar sob tensão constante adoece. O quarto eixo do Acesso Mais Seguro é a gestão do estresse, e ele depende da gestão da escola.</p><ul><li>Depois de uma crise, reúna a equipe para falar do que viveu. Ouvir já ajuda.</li><li>Observe sinais de esgotamento: faltas, irritação, isolamento, choro.</li><li>Encaminhe quem precisa ao serviço de saúde do servidor.</li><li>Não exija que ninguém permaneça em situação de risco.</li><li>Reconheça o trabalho da equipe.</li></ul><div class=\"nota\"><b>Apoio emocional</b><br/>O Centro de Valorização da Vida atende pelo telefone 188, todos os dias, 24 horas, sem custo de ligação.</div>"},{"id":"c10","titulo":"Conhecer o território da escola","html":"<p>Preparar a escola começa por conhecer o lugar onde ela está. Esse conhecimento é construído pela equipe, com quem vive e trabalha no bairro, e é revisto todo semestre.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>O que mapear</th><th>Perguntas</th><th>Fontes</th></tr></thead><tbody><tr><td data-rotulo=\"O que mapear\">De onde vêm os alunos</td><td data-rotulo=\"Perguntas\">De que ruas e localidades? Por quais caminhos? A pé ou de transporte?</td><td data-rotulo=\"Fontes\">Cadastro, professores, transporte escolar.</td></tr><tr><td data-rotulo=\"O que mapear\">Pontos sensíveis</td><td data-rotulo=\"Perguntas\">Que trechos e horários concentram ocorrências?</td><td data-rotulo=\"Fontes\">Servidores que moram no bairro, agentes de saúde.</td></tr><tr><td data-rotulo=\"O que mapear\">Sinais de alerta</td><td data-rotulo=\"Perguntas\">O que muda no bairro antes de um episódio?</td><td data-rotulo=\"Fontes\">Comerciantes, porteiros, responsáveis.</td></tr><tr><td data-rotulo=\"O que mapear\">Serviços e parceiros</td><td data-rotulo=\"Perguntas\">Quem atua no entorno e pode confirmar informações?</td><td data-rotulo=\"Fontes\">Unidade de saúde, CRAS, associações, igrejas.</td></tr><tr><td data-rotulo=\"O que mapear\">Estrutura da escola</td><td data-rotulo=\"Perguntas\">Que salas ficam voltadas para a rua? Onde é mais protegido?</td><td data-rotulo=\"Fontes\">Vistoria com a equipe.</td></tr><tr><td data-rotulo=\"O que mapear\">Histórico</td><td data-rotulo=\"Perguntas\">O que já aconteceu, quando e como a escola agiu?</td><td data-rotulo=\"Fontes\">Registros e memória da equipe.</td></tr></tbody></table></div><h3>A rede de parceiros do território</h3><p>Parceiros são pessoas e serviços que trabalham no bairro e podem dizer, com rapidez, se a situação está normal. A escola combina com eles um modo simples de troca de avisos.</p><ul class=\"chk\"><li><span></span>Unidade básica de saúde e agentes comunitários.</li><li><span></span>CRAS e demais serviços de assistência.</li><li><span></span>Outras escolas e creches do entorno.</li><li><span></span>Transporte escolar.</li><li><span></span>Associação de moradores e lideranças reconhecidas.</li><li><span></span>Comércio vizinho.</li></ul><div class=\"nota alerta\"><b>O mapa é reservado</b><br/>As informações sobre o território ficam com a direção. Não são afixadas, não circulam em grupos e não citam nomes de pessoas.</div><div class=\"pratica\"><div class=\"tt\">Para praticar · o território da sua escola</div><div class=\"q\"><b>1.</b> Quais são os três caminhos mais usados pelos alunos?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Quem são dois parceiros que podem confirmar uma informação em poucos minutos?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> Qual é o local mais protegido de cada bloco da escola?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c11","titulo":"Avaliar o risco e definir níveis de alerta","html":"<p>Nem toda situação pede a mesma resposta. Definir níveis de alerta, com ações combinadas para cada um, evita tanto o pânico quanto a demora.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Nível</th><th>Situação</th><th>O que a escola faz</th></tr></thead><tbody><tr><td data-rotulo=\"Nível\">Normal</td><td data-rotulo=\"Situação\">Sem sinais de alteração no entorno.</td><td data-rotulo=\"O que a escola faz\">Rotina. Plano revisado, equipe orientada, contatos atualizados.</td></tr><tr><td data-rotulo=\"Nível\">Atenção</td><td data-rotulo=\"Situação\">Sinais de tensão: boatos, movimentação incomum, ocorrência recente por perto.</td><td data-rotulo=\"O que a escola faz\">Direção confirma com parceiros e avisa a Secretaria. Atividades externas suspensas. Portões e fluxo de visitantes controlados.</td></tr><tr><td data-rotulo=\"Nível\">Alerta</td><td data-rotulo=\"Situação\">Ocorrência em andamento no entorno, sem atingir a escola.</td><td data-rotulo=\"O que a escola faz\">Alunos permanecem dentro dos prédios, longe de áreas expostas. Ninguém é liberado. Responsáveis são informados pelo canal oficial.</td></tr><tr><td data-rotulo=\"Nível\">Emergência</td><td data-rotulo=\"Situação\">Disparos próximos ou risco direto à escola.</td><td data-rotulo=\"O que a escola faz\">Sinal combinado. Todos nos locais mais seguros, deitados ou abaixados. Acionamento do 190 e da Secretaria.</td></tr></tbody></table></div><figure><div class=\"matriz\"><div class=\"ey\">Gravidade</div><div class=\"grade\"><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Grave e pouco provável</b><small>Ter plano e treinar.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #C44536\"><b>Grave e provável</b><small>Prioridade máxima: medidas imediatas com a Secretaria.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #1E8E5A\"><b>Leve e pouco provável</b><small>Acompanhar.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Leve e provável</b><small>Ajustar rotinas.</small></div></div><div class=\"ex\">Probabilidade</div></div><figcaption>Figura. Como ordenar os riscos identificados.</figcaption></figure><h3>Quem decide</h3><ul><li>Em cada turno há uma pessoa que decide e uma substituta.</li><li>A mudança de nível é comunicada a toda a equipe por um sinal conhecido.</li><li>A suspensão de aulas é decidida com a Secretaria.</li><li>Toda decisão é registrada com data e hora.</li></ul>"},{"id":"c12","titulo":"O plano de segurança da escola","html":"<p>O plano é um documento curto, de duas ou três páginas, que qualquer servidor consegue ler em cinco minutos. Ele é construído com a equipe e aprovado pela Secretaria.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Parte</th><th>Conteúdo</th></tr></thead><tbody><tr><td data-rotulo=\"Parte\">Responsáveis</td><td data-rotulo=\"Conteúdo\">Quem decide em cada turno, quem substitui e quem fala com a Secretaria e com os responsáveis.</td></tr><tr><td data-rotulo=\"Parte\">Níveis de alerta</td><td data-rotulo=\"Conteúdo\">O que caracteriza cada nível e o que fazer.</td></tr><tr><td data-rotulo=\"Parte\">Sinais</td><td data-rotulo=\"Conteúdo\">Como a equipe é avisada: sinal sonoro, mensagem, aviso de sala em sala.</td></tr><tr><td data-rotulo=\"Parte\">Locais mais seguros</td><td data-rotulo=\"Conteúdo\">Para cada bloco e turma, onde ficar e por onde ir.</td></tr><tr><td data-rotulo=\"Parte\">Pessoas que precisam de apoio</td><td data-rotulo=\"Conteúdo\">Alunos com deficiência, crianças menores, quem está fora da sala.</td></tr><tr><td data-rotulo=\"Parte\">Entrada e saída</td><td data-rotulo=\"Conteúdo\">Como os alunos chegam, saem e são entregues aos responsáveis em dias de risco.</td></tr><tr><td data-rotulo=\"Parte\">Comunicação</td><td data-rotulo=\"Conteúdo\">Lista de telefones, canal oficial com as famílias e mensagens-modelo.</td></tr><tr><td data-rotulo=\"Parte\">Depois da crise</td><td data-rotulo=\"Conteúdo\">Verificação, acolhimento, registro e retomada.</td></tr><tr><td data-rotulo=\"Parte\">Formação e revisão</td><td data-rotulo=\"Conteúdo\">Quando a equipe treina e quando o plano é revisto.</td></tr></tbody></table></div><h3>Como escolher o local mais seguro</h3><ul><li>Longe de janelas, portas de vidro e paredes voltadas para a rua.</li><li>De preferência no térreo e no interior do prédio, como corredores internos.</li><li>Com paredes de alvenaria entre as pessoas e a rua.</li><li>Com espaço para todos ficarem deitados ou sentados no chão.</li><li>Conhecido por todos e sinalizado de forma discreta.</li></ul><h3>Treinar sem assustar</h3><ol class=\"passos\"><li>Explique aos alunos, com calma, que a escola tem um combinado para manter todos seguros, como tem para incêndio.</li><li>Ensine o procedimento em sala: ao sinal, abaixar, afastar-se das janelas, seguir o professor.</li><li>Faça o percurso até o local mais seguro, sem pressa.</li><li>Não use sons de disparos nem simule cenas de violência.</li><li>Converse depois: o que funcionou, quem ficou com medo, o que mudar.</li><li>Repita a cada semestre e sempre que chegarem alunos novos.</li></ol><div class=\"nota\"><b>Informar os responsáveis</b><br/>No início do ano, a escola explica às famílias como age em situações de risco e por que os alunos não são liberados durante uma ocorrência. Famílias informadas confiam mais e correm menos para a porta da escola.</div>"},{"id":"c13","titulo":"Comunicação durante a crise","html":"<p>Na crise, a falta de informação gera boatos, e os boatos levam os responsáveis a se deslocarem para a escola no pior momento. Mensagens curtas, verdadeiras e frequentes protegem.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Para quem</th><th>O que comunicar</th><th>Por onde</th><th>Quem</th></tr></thead><tbody><tr><td data-rotulo=\"Para quem\">Equipe</td><td data-rotulo=\"O que comunicar\">Nível de alerta e o que fazer.</td><td data-rotulo=\"Por onde\">Sinal combinado e grupo de servidores.</td><td data-rotulo=\"Quem\">Direção</td></tr><tr><td data-rotulo=\"Para quem\">Secretaria</td><td data-rotulo=\"O que comunicar\">O que ocorre, desde quando, medidas tomadas e do que a escola precisa.</td><td data-rotulo=\"Por onde\">Telefone direto.</td><td data-rotulo=\"Quem\">Direção</td></tr><tr><td data-rotulo=\"Para quem\">Segurança pública e SAMU</td><td data-rotulo=\"O que comunicar\">Local, o que ocorre, se há feridos.</td><td data-rotulo=\"Por onde\">190 e 192.</td><td data-rotulo=\"Quem\">Direção ou substituto</td></tr><tr><td data-rotulo=\"Para quem\">Responsáveis</td><td data-rotulo=\"O que comunicar\">Os alunos estão protegidos. Não venham agora. A escola avisará.</td><td data-rotulo=\"Por onde\">Canal oficial.</td><td data-rotulo=\"Quem\">Pessoa designada</td></tr><tr><td data-rotulo=\"Para quem\">Imprensa</td><td data-rotulo=\"O que comunicar\">Encaminhar à Secretaria.</td><td data-rotulo=\"Por onde\"></td><td data-rotulo=\"Quem\">Secretaria</td></tr></tbody></table></div><h3>Mensagens-modelo para os responsáveis</h3><div class=\"rapido\"><p><b>Durante:</b> \"Senhores responsáveis: há uma ocorrência nas proximidades da escola. Todos os alunos estão dentro do prédio, protegidos e acompanhados. Por segurança, pedimos que não venham à escola agora. Daremos nova informação em breve. Direção.\"</p><p><b>Liberação:</b> \"Senhores responsáveis: a situação no entorno foi normalizada. A saída dos alunos será feita a partir das ____ horas, pelo portão ____. Os alunos menores serão entregues somente aos responsáveis. Direção.\"</p><p><b>Suspensão de aulas:</b> \"Senhores responsáveis: por orientação da Secretaria Municipal de Educação, não haverá aula amanhã, dia ____. Informaremos o retorno por este canal. Direção.\"</p><p><b>Retorno:</b> \"Senhores responsáveis: as aulas serão retomadas amanhã, dia ____, no horário normal. A equipe estará preparada para acolher os alunos. Direção.\"</p></div><h3>Cuidados</h3><ul><li>Não informar detalhes da ocorrência, apenas o que afeta os alunos.</li><li>Não citar pessoas, grupos ou locais além do necessário.</li><li>Repetir a informação em intervalos regulares, mesmo sem novidade.</li><li>Não responder a boatos um a um. Reafirmar o canal oficial.</li><li>Guardar cópia das mensagens enviadas.</li></ul>"},{"id":"c14","titulo":"Suspender, retomar e repor aulas","html":"<p>Fechar a escola protege em um dia de risco, mas cada dia sem aula também tem custo: os alunos perdem conteúdo, alimentação e proteção. A decisão é tomada com a Secretaria, com base em informação confirmada.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Decisão provável</th><th>Observações</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Risco confirmado antes do início do turno</td><td data-rotulo=\"Decisão provável\">Não abrir o turno.</td><td data-rotulo=\"Observações\">Avisar os responsáveis e o transporte escolar o mais cedo possível.</td></tr><tr><td data-rotulo=\"Situação\">Risco surge com os alunos na escola</td><td data-rotulo=\"Decisão provável\">Manter todos na escola até a normalização.</td><td data-rotulo=\"Observações\">Não liberar durante a ocorrência.</td></tr><tr><td data-rotulo=\"Situação\">Risco na hora da saída</td><td data-rotulo=\"Decisão provável\">Adiar a saída.</td><td data-rotulo=\"Observações\">Entrega aos responsáveis. Combinar com o transporte.</td></tr><tr><td data-rotulo=\"Situação\">Tensão que se prolonga por dias</td><td data-rotulo=\"Decisão provável\">Avaliação diária com a Secretaria.</td><td data-rotulo=\"Observações\">Considerar horário reduzido e atividades para casa.</td></tr><tr><td data-rotulo=\"Situação\">Boato não confirmado</td><td data-rotulo=\"Decisão provável\">Manter as aulas e informar os responsáveis.</td><td data-rotulo=\"Observações\">Registrar a origem do boato.</td></tr></tbody></table></div><h3>O primeiro dia de volta</h3><ol class=\"passos\"><li>A equipe se reúne antes da entrada dos alunos.</li><li>Os alunos são recebidos no portão pelos adultos da escola.</li><li>A primeira aula reserva tempo para quem quiser falar, sem obrigar ninguém.</li><li>A rotina é retomada com atividades mais leves.</li><li>Os professores observam quem está muito abalado e avisam a coordenação.</li><li>A alimentação escolar é garantida.</li></ol><h3>Reposição e aprendizagem</h3><ul><li>O calendário letivo é recomposto conforme as orientações da Secretaria, para garantir os dias e as horas previstos em lei.</li><li>A frequência é acompanhada: alunos que não voltam entram na busca ativa.</li><li>O reforço escolar ajuda a recuperar os conteúdos, e o aluno pode estudar em casa quando há equipamento e conexão.</li><li>Provas e prazos são reorganizados sem prejuízo para os alunos.</li></ul><div class=\"nota\"><b>Faltas em dias de risco</b><br/>A ausência de alunos em dias de ocorrência no bairro é tratada com compreensão. A escola procura a família para saber como estão, e não para cobrar.</div>"},{"id":"c15","titulo":"Pressões sobre a escola","html":"<p>Em alguns territórios, a escola recebe pedidos e recados que não vêm da Secretaria: fechar em determinado dia, liberar o espaço, mudar um horário, matricular ou transferir alguém. Nenhum gestor deve lidar com isso sozinho.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Conduta</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Recado para fechar a escola</td><td data-rotulo=\"Conduta\">Não discutir com o portador. Comunicar imediatamente à Secretaria, que decide com os órgãos competentes.</td></tr><tr><td data-rotulo=\"Situação\">Pedido de uso do prédio ou da quadra</td><td data-rotulo=\"Conduta\">Informar que o uso depende de autorização da Secretaria. Registrar e comunicar.</td></tr><tr><td data-rotulo=\"Situação\">Oferta de doação, festa ou reforma</td><td data-rotulo=\"Conduta\">Agradecer, informar que a escola só recebe doações pelos meios oficiais e comunicar.</td></tr><tr><td data-rotulo=\"Situação\">Pressão para favorecer ou prejudicar um aluno</td><td data-rotulo=\"Conduta\">Aplicar as regras da rede, iguais para todos. Comunicar.</td></tr><tr><td data-rotulo=\"Situação\">Pedido de informação sobre aluno, família ou servidor</td><td data-rotulo=\"Conduta\">Não fornecer. Dados são protegidos por lei.</td></tr><tr><td data-rotulo=\"Situação\">Presença de pessoas armadas nas proximidades</td><td data-rotulo=\"Conduta\">Recolher os alunos para dentro, sem alarde, e seguir o nível de alerta.</td></tr><tr><td data-rotulo=\"Situação\">Ameaça a um servidor</td><td data-rotulo=\"Conduta\">Proteger o servidor, comunicar à Secretaria no mesmo momento e registrar ocorrência.</td></tr></tbody></table></div><h3>Como se portar em um contato</h3><ul><li>Manter a calma, o tom respeitoso e frases curtas.</li><li>Não prometer, não negociar e não confrontar.</li><li>Dizer que decisões sobre a escola são da Secretaria.</li><li>Não ficar sozinho: ter outro servidor por perto.</li><li>Encerrar o contato assim que possível.</li><li>Registrar por escrito, logo depois, o que foi dito, sem identificar pessoas além do necessário.</li></ul><div class=\"nota alerta\"><b>Não é decisão da escola</b><br/>Acordos locais colocam o gestor em risco e comprometem a neutralidade da escola. Todo contato desse tipo é levado à Secretaria no mesmo dia, pelo canal reservado.</div>"},{"id":"c16","titulo":"Relação com as forças de segurança","html":"<p>A escola colabora com as autoridades dentro da lei e do seu papel. Ela não é fonte de informação sobre moradores, e os servidores não atuam como intermediários.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Conduta da direção</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Ronda escolar e ações preventivas</td><td data-rotulo=\"Conduta da direção\">Receber, combinar horários e manter o contato institucional pela Secretaria.</td></tr><tr><td data-rotulo=\"Situação\">Operação policial no entorno</td><td data-rotulo=\"Conduta da direção\">Seguir o nível de alerta. Manter os alunos protegidos. Informar a Secretaria.</td></tr><tr><td data-rotulo=\"Situação\">Pedido de entrada na escola durante operação</td><td data-rotulo=\"Conduta da direção\">Atender à autoridade, proteger os alunos e comunicar à Secretaria imediatamente.</td></tr><tr><td data-rotulo=\"Situação\">Pedido de informações ou de documentos de alunos</td><td data-rotulo=\"Conduta da direção\">Solicitar o pedido formal, por escrito, e encaminhar à Secretaria.</td></tr><tr><td data-rotulo=\"Situação\">Ouvir um aluno na escola</td><td data-rotulo=\"Conduta da direção\">A escola não realiza nem permite interrogatórios. Chamar os responsáveis e o Conselho Tutelar.</td></tr><tr><td data-rotulo=\"Situação\">Crime dentro da escola</td><td data-rotulo=\"Conduta da direção\">Proteger as pessoas, preservar o local, acionar o 190 e a Secretaria.</td></tr></tbody></table></div><h3>Substâncias e armas na escola</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>O que fazer</th><th>O que não fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Aluno com sinais de uso de substância</td><td data-rotulo=\"O que fazer\">Acolher, cuidar da saúde, chamar os responsáveis, encaminhar à rede de saúde.</td><td data-rotulo=\"O que não fazer\">Expor, humilhar ou revistar diante de colegas.</td></tr><tr><td data-rotulo=\"Situação\">Substância encontrada com aluno</td><td data-rotulo=\"O que fazer\">Recolher com testemunha, guardar em local seguro, chamar os responsáveis e seguir a orientação da Secretaria.</td><td data-rotulo=\"O que não fazer\">Devolver, descartar por conta própria ou divulgar.</td></tr><tr><td data-rotulo=\"Situação\">Suspeita de venda na escola</td><td data-rotulo=\"O que fazer\">Comunicar à Secretaria e ao Conselho Tutelar. Tratar o adolescente como pessoa em situação de exploração.</td><td data-rotulo=\"O que não fazer\">Investigar, montar flagrante ou confrontar.</td></tr><tr><td data-rotulo=\"Situação\">Arma ou objeto perigoso com aluno</td><td data-rotulo=\"O que fazer\">Manter a calma, afastar os demais, pedir que o objeto seja deixado em local indicado, acionar o 190.</td><td data-rotulo=\"O que não fazer\">Tentar tomar à força.</td></tr><tr><td data-rotulo=\"Situação\">Arma ou munição encontrada</td><td data-rotulo=\"O que fazer\">Isolar o local, não tocar, acionar o 190.</td><td data-rotulo=\"O que não fazer\">Manusear, guardar ou fotografar para grupos.</td></tr></tbody></table></div><div class=\"nota\"><b>Revista de alunos</b><br/>Servidores da escola não fazem revista pessoal. Diante de suspeita fundada de risco, a direção isola a situação e aciona a autoridade competente e os responsáveis.</div>"},{"id":"c17","titulo":"Como a violência afeta a aprendizagem","html":"<p>Crianças e adolescentes que convivem com tiroteios, ameaças, perdas e medo constante vivem em estado de alerta. O corpo se prepara o tempo todo para o perigo, e sobra pouca energia para prestar atenção, memorizar e controlar impulsos.</p><p>Muitos comportamentos que a escola lê como desinteresse ou indisciplina são, nesses casos, respostas de quem aprendeu a se proteger.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>O que a escola vê</th><th>O que pode estar acontecendo</th></tr></thead><tbody><tr><td data-rotulo=\"O que a escola vê\">Sono em sala</td><td data-rotulo=\"O que pode estar acontecendo\">Noites sem dormir por medo, barulho ou vigília.</td></tr><tr><td data-rotulo=\"O que a escola vê\">Sustos e reações exageradas a ruídos</td><td data-rotulo=\"O que pode estar acontecendo\">Estado de alerta permanente.</td></tr><tr><td data-rotulo=\"O que a escola vê\">Explosões de raiva por motivos pequenos</td><td data-rotulo=\"O que pode estar acontecendo\">Dificuldade de regular emoções sob tensão.</td></tr><tr><td data-rotulo=\"O que a escola vê\">\"Desligamento\", olhar distante</td><td data-rotulo=\"O que pode estar acontecendo\">Forma de se afastar de lembranças e do medo.</td></tr><tr><td data-rotulo=\"O que a escola vê\">Esquecimento do que foi ensinado ontem</td><td data-rotulo=\"O que pode estar acontecendo\">A tensão prejudica a memória.</td></tr><tr><td data-rotulo=\"O que a escola vê\">Desconfiança de adultos</td><td data-rotulo=\"O que pode estar acontecendo\">Experiências em que adultos não protegeram.</td></tr><tr><td data-rotulo=\"O que a escola vê\">Faltas em determinados dias</td><td data-rotulo=\"O que pode estar acontecendo\">Trajeto inseguro, operações, luto na família.</td></tr><tr><td data-rotulo=\"O que a escola vê\">Brincadeiras e desenhos com armas e mortes</td><td data-rotulo=\"O que pode estar acontecendo\">Tentativa de dar sentido ao que viu.</td></tr></tbody></table></div><h3>O que ajuda: quatro pilares</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Pilar</th><th>Na prática</th></tr></thead><tbody><tr><td data-rotulo=\"Pilar\">Segurança</td><td data-rotulo=\"Na prática\">O aluno sabe que na escola nenhum adulto vai gritar, humilhar ou agredir.</td></tr><tr><td data-rotulo=\"Pilar\">Previsibilidade</td><td data-rotulo=\"Na prática\">Rotina conhecida, avisos antes de mudanças, combinados estáveis.</td></tr><tr><td data-rotulo=\"Pilar\">Vínculo</td><td data-rotulo=\"Na prática\">Pelo menos um adulto que sabe o nome dele, nota quando falta e pergunta como está.</td></tr><tr><td data-rotulo=\"Pilar\">Escolha</td><td data-rotulo=\"Na prática\">Pequenas decisões ao alcance dele: onde sentar, por qual atividade começar.</td></tr></tbody></table></div><div class=\"nota\"><b>Entender não é desculpar</b><br/>Compreender a origem do comportamento não significa abrir mão das regras. Significa aplicá-las com calma, sem humilhação, e ensinar o que o aluno ainda não sabe fazer.</div>"},{"id":"c18","titulo":"Luto na escola","html":"<p>A morte de um familiar, de um colega ou de alguém do bairro chega à escola no dia seguinte. A escola não precisa ter respostas. Precisa reconhecer a perda, acolher e manter a rotina.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Idade</th><th>Como costuma reagir</th><th>O que ajuda</th></tr></thead><tbody><tr><td data-rotulo=\"Idade\">6 a 8 anos</td><td data-rotulo=\"Como costuma reagir\">Faz perguntas diretas e repetidas. Alterna tristeza e brincadeira. Pode achar que causou a morte.</td><td data-rotulo=\"O que ajuda\">Respostas simples e verdadeiras. Dizer que não foi culpa dela. Desenho e brincadeira.</td></tr><tr><td data-rotulo=\"Idade\">9 a 11 anos</td><td data-rotulo=\"Como costuma reagir\">Entende que a morte é definitiva. Sente medo de perder outras pessoas. Pode ter dores sem causa médica.</td><td data-rotulo=\"O que ajuda\">Espaço para falar. Rotina. Atenção a faltas e queda no rendimento.</td></tr><tr><td data-rotulo=\"Idade\">12 a 14 anos</td><td data-rotulo=\"Como costuma reagir\">Esconde o que sente. Pode reagir com raiva, isolamento ou comportamento de risco. Em mortes violentas, pode falar em vingança.</td><td data-rotulo=\"O que ajuda\">Conversa em particular, sem pressa. Um adulto de referência. Encaminhamento quando há ideias de revide ou de autolesão.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Dizer</th><th>Evitar</th></tr></thead><tbody><tr><td data-rotulo=\"Dizer\">\"Sinto muito pelo que aconteceu.\"</td><td data-rotulo=\"Evitar\">\"Eu sei como você se sente.\"</td></tr><tr><td data-rotulo=\"Dizer\">\"Estou aqui se você quiser conversar.\"</td><td data-rotulo=\"Evitar\">\"Você precisa ser forte.\"</td></tr><tr><td data-rotulo=\"Dizer\">\"Tudo bem chorar.\"</td><td data-rotulo=\"Evitar\">\"Não chore.\"</td></tr><tr><td data-rotulo=\"Dizer\">\"Não tenho resposta, mas estou com você.\"</td><td data-rotulo=\"Evitar\">\"Foi melhor assim\" ou \"foi vontade de Deus\".</td></tr><tr><td data-rotulo=\"Dizer\">\"Quer fazer a atividade agora ou depois?\"</td><td data-rotulo=\"Evitar\">\"A vida continua.\"</td></tr></tbody></table></div><h3>Quando morre um aluno ou um servidor</h3><ol class=\"passos\"><li>A direção confirma a informação com a família antes de falar.</li><li>A equipe é reunida e avisada primeiro.</li><li>Cada turma é avisada pelo próprio professor, em sala, com palavras simples e sem detalhes da morte.</li><li>A escola reserva um tempo para os alunos falarem, escreverem ou desenharem.</li><li>A rotina é retomada no mesmo dia, com flexibilidade.</li><li>A escola combina com a família como participar das despedidas.</li><li>Nas semanas seguintes, os professores observam os alunos mais próximos.</li></ol><div class=\"nota alerta\"><b>Em mortes violentas</b><br/>Não se comentam as circunstâncias, não se apontam culpados e não se compartilham imagens. Homenagens são simples e iguais para todos, sem exaltar a forma da morte.</div>"},{"id":"c19","titulo":"Quando o crime tenta atrair alunos","html":"<p>Em alguns territórios, grupos criminosos procuram adolescentes, e às vezes crianças, para tarefas como vigiar, transportar e vender. A aproximação raramente começa com ameaça. Começa com dinheiro, presentes, proteção e a sensação de pertencer a um grupo.</p><p>A lei trata esses adolescentes como vítimas de exploração. O uso de crianças e adolescentes no tráfico está na lista das piores formas de trabalho infantil (Decreto nº 6.481/2008).</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Fatores de risco</th><th>Fatores de proteção</th></tr></thead><tbody><tr><td data-rotulo=\"Fatores de risco\">Faltas e abandono escolar.</td><td data-rotulo=\"Fatores de proteção\">Frequência e vínculo com a escola.</td></tr><tr><td data-rotulo=\"Fatores de risco\">Sensação de não ter futuro pelo estudo.</td><td data-rotulo=\"Fatores de proteção\">Experiências de sucesso e projeto de vida.</td></tr><tr><td data-rotulo=\"Fatores de risco\">Necessidade de renda na família.</td><td data-rotulo=\"Fatores de proteção\">Acesso a programas sociais e de aprendizagem profissional.</td></tr><tr><td data-rotulo=\"Fatores de risco\">Familiares ou amigos envolvidos.</td><td data-rotulo=\"Fatores de proteção\">Um adulto de referência fora desse círculo.</td></tr><tr><td data-rotulo=\"Fatores de risco\">Humilhação e exclusão na escola.</td><td data-rotulo=\"Fatores de proteção\">Respeito e pertencimento na turma.</td></tr><tr><td data-rotulo=\"Fatores de risco\">Tempo livre sem supervisão.</td><td data-rotulo=\"Fatores de proteção\">Esporte, cultura e atividades no contraturno.</td></tr></tbody></table></div><h3>Sinais que pedem atenção</h3><ul><li>Dinheiro, roupas ou aparelhos sem explicação.</li><li>Novo grupo de amizades, mais velho, e afastamento dos colegas antigos.</li><li>Faltas que aumentam, sono em sala, saídas antes do fim da aula.</li><li>Gírias, gestos e símbolos ligados a grupos do território.</li><li>Mudança de postura: desafio aos adultos ou, ao contrário, medo e silêncio.</li><li>Comentários sobre dívidas, ameaças ou \"missões\".</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>A escola faz</th><th>A escola não faz</th></tr></thead><tbody><tr><td data-rotulo=\"A escola faz\">Mantém o aluno na escola a todo custo.</td><td data-rotulo=\"A escola não faz\">Não expulsa, não transfere como punição e não rotula.</td></tr><tr><td data-rotulo=\"A escola faz\">Conversa sobre futuro, sem sermão.</td><td data-rotulo=\"A escola não faz\">Não interroga sobre o envolvimento.</td></tr><tr><td data-rotulo=\"A escola faz\">Leva à direção, que aciona a rede de proteção.</td><td data-rotulo=\"A escola não faz\">Não confronta pessoas do território.</td></tr><tr><td data-rotulo=\"A escola faz\">Oferece atividades, responsabilidades e reconhecimento.</td><td data-rotulo=\"A escola não faz\">Não repassa nomes ou informações a ninguém fora da rede de proteção.</td></tr><tr><td data-rotulo=\"A escola faz\">Trata com a família, com cuidado.</td><td data-rotulo=\"A escola não faz\">Não expõe a suspeita a colegas ou a outros responsáveis.</td></tr></tbody></table></div><div class=\"nota\"><b>Adolescentes ameaçados</b><br/>Quando há ameaça de morte contra um aluno, a direção comunica imediatamente ao Conselho Tutelar e à Secretaria. Existe um programa federal de proteção a crianças e adolescentes ameaçados de morte, acionado pelo Conselho Tutelar, pelo Ministério Público ou pela Justiça.</div>"},{"id":"c20","titulo":"Atendimento a responsáveis em situações tensas","html":"<p>A maioria dos conflitos com famílias se resolve com escuta. Alguns envolvem ameaça. A direção precisa de um modo de atender que proteja a equipe sem fechar a porta à família.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Medida</th><th>Como aplicar</th></tr></thead><tbody><tr><td data-rotulo=\"Medida\">Local</td><td data-rotulo=\"Como aplicar\">Sala próxima à entrada, com porta que possa ficar aberta, e saída livre para o servidor.</td></tr><tr><td data-rotulo=\"Medida\">Companhia</td><td data-rotulo=\"Como aplicar\">Atendimentos difíceis são feitos por duas pessoas.</td></tr><tr><td data-rotulo=\"Medida\">Horário</td><td data-rotulo=\"Como aplicar\">Marcar horário, sempre que possível, em vez de atender na porta ou na sala de aula.</td></tr><tr><td data-rotulo=\"Medida\">Registro</td><td data-rotulo=\"Como aplicar\">Anotar data, assunto e combinados. O responsável é informado do registro.</td></tr><tr><td data-rotulo=\"Medida\">Professor</td><td data-rotulo=\"Como aplicar\">Responsável alterado não é levado à sala de aula. A direção atende primeiro.</td></tr><tr><td data-rotulo=\"Medida\">Limite</td><td data-rotulo=\"Como aplicar\">Diante de gritos ou ofensas, encerrar com calma e remarcar.</td></tr><tr><td data-rotulo=\"Medida\">Segurança</td><td data-rotulo=\"Como aplicar\">Diante de ameaça, proteger o servidor, registrar e comunicar à Secretaria. Em risco imediato, acionar o 190.</td></tr></tbody></table></div><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · o responsável que chega alterado</div><div class=\"f\"><div class=\"q\">Direção</div><div class=\"b\">Bom dia. Vejo que o senhor está muito preocupado. Vamos conversar na minha sala.</div></div><div class=\"f o\"><div class=\"q\">Responsável</div><div class=\"b\">Eu quero falar com essa professora agora!</div></div><div class=\"f\"><div class=\"q\">Direção</div><div class=\"b\">Entendo. Primeiro quero ouvir o senhor, para resolver da melhor forma. O que aconteceu?</div></div><div class=\"f o\"><div class=\"q\">Responsável</div><div class=\"b\">Meu filho disse que ela gritou com ele na frente de todo mundo.</div></div><div class=\"f\"><div class=\"q\">Direção</div><div class=\"b\">Obrigada por me contar. Vou anotar, ouvir a professora e o seu filho, e dou um retorno ao senhor até amanhã. Pode ser?</div></div><div class=\"f o\"><div class=\"q\">Responsável</div><div class=\"b\">Se isso não se resolver, eu resolvo do meu jeito.</div></div><div class=\"f\"><div class=\"q\">Direção</div><div class=\"b\">Vou tratar com seriedade. Peço que o senhor também trate com a escola pelo diálogo. Ameaças eu sou obrigada a registrar. Amanhã, às dez horas, o senhor pode voltar?</div></div></div><h3>Depois do atendimento</h3><ul><li>Cumprir o prazo de retorno, mesmo que ainda não haja solução.</li><li>Ouvir o servidor citado em particular, sem prejulgar.</li><li>Ouvir o aluno com cuidado.</li><li>Registrar o desfecho.</li><li>Quando a queixa procede, reconhecer e dizer o que a escola fará.</li></ul><div class=\"nota\"><b>O que a lei prevê</b><br/>Ameaçar e desacatar servidor público no exercício da função são crimes previstos no Código Penal. A direção registra e comunica à Secretaria, que orienta as providências. O objetivo continua sendo proteger a equipe e manter o aluno na escola.</div>"},{"id":"c21","titulo":"Alunos em risco de abandonar a escola","html":"<p>Em territórios com violência, o abandono escolar raramente é uma decisão. É o resultado de medo no trajeto, mudança forçada de endereço, luto, trabalho ou envolvimento com grupos. Cada aluno que sai fica mais exposto.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Motivo</th><th>Sinais</th><th>O que a escola pode fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Motivo\">Trajeto inseguro</td><td data-rotulo=\"Sinais\">Faltas em dias ou horários específicos.</td><td data-rotulo=\"O que a escola pode fazer\">Levar à Secretaria: rota do transporte, mudança de turno, vaga em escola mais próxima.</td></tr><tr><td data-rotulo=\"Motivo\">Não pode circular em certas áreas</td><td data-rotulo=\"Sinais\">Aluno ou família pede transferência sem explicar.</td><td data-rotulo=\"O que a escola pode fazer\">Atender com rapidez e discrição. Não exigir justificativa detalhada.</td></tr><tr><td data-rotulo=\"Motivo\">Família saiu às pressas</td><td data-rotulo=\"Sinais\">Aluno some. Vizinhos dizem que se mudaram.</td><td data-rotulo=\"O que a escola pode fazer\">Acionar a Secretaria e o Conselho Tutelar para localizar a nova matrícula.</td></tr><tr><td data-rotulo=\"Motivo\">Luto e medo</td><td data-rotulo=\"Sinais\">Faltas depois de uma morte ou de um episódio.</td><td data-rotulo=\"O que a escola pode fazer\">Visita ou contato de acolhimento. Flexibilizar prazos.</td></tr><tr><td data-rotulo=\"Motivo\">Trabalho</td><td data-rotulo=\"Sinais\">Cansaço, faltas, renda própria.</td><td data-rotulo=\"O que a escola pode fazer\">CRAS, programas sociais e aprendizagem profissional.</td></tr><tr><td data-rotulo=\"Motivo\">Envolvimento com grupos</td><td data-rotulo=\"Sinais\">Mudança de amizades, dinheiro, afastamento.</td><td data-rotulo=\"O que a escola pode fazer\">Manter o vínculo, acionar a rede de proteção, não rotular.</td></tr><tr><td data-rotulo=\"Motivo\">Gravidez e cuidado de irmãos</td><td data-rotulo=\"Sinais\">Faltas e atrasos.</td><td data-rotulo=\"O que a escola pode fazer\">Rede de saúde e assistência. Garantia legal de permanência.</td></tr></tbody></table></div><h3>Busca ativa em cinco passos</h3><ol class=\"passos\"><li>O professor avisa a secretaria da escola na terceira falta seguida.</li><li>A escola faz contato com os responsáveis no mesmo dia.</li><li>Sem contato, um servidor ou parceiro do território procura a família, com segurança.</li><li>A direção comunica ao Conselho Tutelar quando as faltas passam do limite legal ou quando há indício de violação de direitos.</li><li>A escola prepara a volta: acolhida, recuperação dos conteúdos e um adulto de referência.</li></ol><div class=\"nota alerta\"><b>Dever legal</b><br/>A Lei de Diretrizes e Bases determina que a escola notifique ao Conselho Tutelar a relação dos alunos com faltas acima de trinta por cento do percentual permitido em lei.</div>"},{"id":"c22","titulo":"Boatos, redes sociais e ameaças","html":"<p>Mensagens sobre tiroteios, toques de recolher e ameaças a escolas se espalham em minutos pelos grupos. Muitas são falsas, antigas ou de outra cidade. Mesmo assim, esvaziam a escola e geram pânico.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Receber</b><small>não repassar</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Verificar</b><small>com a direção e fontes oficiais</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Comunicar</b><small>à Secretaria</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Informar</b><small>famílias, por canal oficial</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Registrar</b><small>o que ocorreu</small></div></div><figcaption>Figura. O que fazer ao receber uma mensagem alarmante.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Conduta</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Mensagem sobre confronto no bairro</td><td data-rotulo=\"Conduta\">A direção confirma com parceiros do território e com a Secretaria antes de qualquer decisão.</td></tr><tr><td data-rotulo=\"Situação\">Boato de \"toque de recolher\"</td><td data-rotulo=\"Conduta\">A direção comunica à Secretaria, que orienta. A escola não divulga o boato.</td></tr><tr><td data-rotulo=\"Situação\">Ameaça de ataque à escola em rede social</td><td data-rotulo=\"Conduta\">Guardar a imagem da mensagem, comunicar à direção e à Secretaria, que acionam a polícia. Não compartilhar.</td></tr><tr><td data-rotulo=\"Situação\">Aluno que escreve ou desenha ameaças</td><td data-rotulo=\"Conduta\">Tratar com seriedade e sem pânico. Conversar em particular, comunicar à direção e chamar a família.</td></tr><tr><td data-rotulo=\"Situação\">Responsáveis pedem informação</td><td data-rotulo=\"Conduta\">Responder apenas pelo canal oficial da escola, com o que foi confirmado.</td></tr><tr><td data-rotulo=\"Situação\">Imprensa procura a escola</td><td data-rotulo=\"Conduta\">Encaminhar à Secretaria. Servidores não dão entrevistas sobre ocorrências.</td></tr></tbody></table></div><h3>Regras para os grupos de mensagens</h3><ul><li>A escola tem um canal oficial, e os responsáveis sabem qual é.</li><li>Servidores não repassam áudios, vídeos e mensagens não confirmados.</li><li>Nenhuma imagem de alunos, de vítimas ou de ocorrências é compartilhada.</li><li>Informações sobre o território não são comentadas em grupos.</li><li>Quem recebe algo preocupante envia só à direção.</li></ul><div class=\"nota alerta\"><b>Ameaças de ataque</b><br/>Toda ameaça é comunicada, mesmo que pareça brincadeira. Quem avalia a gravidade é a autoridade policial. A escola cuida de acolher, informar com calma e manter a rotina que for possível.</div>"},{"id":"c23","titulo":"Neutralidade e cuidado com as palavras","html":"<p>A escola atende filhos de todas as famílias do território, inclusive de pessoas envolvidas com o crime, de vítimas e de agentes de segurança. Para continuar sendo um lugar seguro para todos, ela não toma partido.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>Como se traduz no dia a dia</th></tr></thead><tbody><tr><td data-rotulo=\"Princípio\">Todos os alunos são alunos</td><td data-rotulo=\"Como se traduz no dia a dia\">Nenhum aluno é tratado de modo diferente pelo que a família faz ou pelo lugar onde mora.</td></tr><tr><td data-rotulo=\"Princípio\">A escola não comenta o território</td><td data-rotulo=\"Como se traduz no dia a dia\">Servidores não opinam sobre grupos, operações ou pessoas diante de alunos e responsáveis.</td></tr><tr><td data-rotulo=\"Princípio\">A escola não repassa informação</td><td data-rotulo=\"Como se traduz no dia a dia\">O que se sabe sobre alunos e famílias fica na escola e na rede de proteção.</td></tr><tr><td data-rotulo=\"Princípio\">A escola não aceita favores</td><td data-rotulo=\"Como se traduz no dia a dia\">Doações, festas e \"ajudas\" de origem duvidosa são recusadas com educação e comunicadas à Secretaria.</td></tr><tr><td data-rotulo=\"Princípio\">A escola não media disputas</td><td data-rotulo=\"Como se traduz no dia a dia\">Conflitos do território não são resolvidos dentro da escola.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Evitar dizer</th><th>Prefira</th></tr></thead><tbody><tr><td data-rotulo=\"Evitar dizer\">\"Aqui só tem bandido.\"</td><td data-rotulo=\"Prefira\">\"Este bairro enfrenta muita violência.\"</td></tr><tr><td data-rotulo=\"Evitar dizer\">\"Filho de traficante.\"</td><td data-rotulo=\"Prefira\">O nome do aluno.</td></tr><tr><td data-rotulo=\"Evitar dizer\">\"Esse aí já está perdido.\"</td><td data-rotulo=\"Prefira\">\"Esse aluno precisa de mais apoio.\"</td></tr><tr><td data-rotulo=\"Evitar dizer\">\"Você vai acabar como seu irmão.\"</td><td data-rotulo=\"Prefira\">\"Você pode escolher o seu caminho, e eu quero ajudar.\"</td></tr><tr><td data-rotulo=\"Evitar dizer\">\"A polícia tem que acabar com eles.\"</td><td data-rotulo=\"Prefira\">Não comentar.</td></tr><tr><td data-rotulo=\"Evitar dizer\">\"Lá na área de vocês...\"</td><td data-rotulo=\"Prefira\">\"No bairro...\"</td></tr></tbody></table></div><div class=\"nota\"><b>O que o aluno ouve</b><br/>Uma frase dita por um adulto da escola sobre o bairro ou sobre a família é levada para casa. Pode ferir o aluno e pode colocar o servidor em risco.</div>"},{"id":"c24","titulo":"Formar e cuidar da equipe","html":"<p>Um plano só funciona se as pessoas o conhecem e se sentem amparadas. Em escolas expostas à violência, o desgaste da equipe é alto e aparece em faltas, adoecimento e pedidos de remoção.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Quando</th><th>Ação de formação</th></tr></thead><tbody><tr><td data-rotulo=\"Quando\">Início do ano</td><td data-rotulo=\"Ação de formação\">Apresentar o plano de segurança. Percorrer os locais mais seguros. Atualizar contatos.</td></tr><tr><td data-rotulo=\"Quando\">Chegada de novo servidor</td><td data-rotulo=\"Ação de formação\">Orientação individual no primeiro dia: sinais, locais e a quem recorrer.</td></tr><tr><td data-rotulo=\"Quando\">A cada semestre</td><td data-rotulo=\"Ação de formação\">Treino do procedimento com as turmas. Revisão do plano.</td></tr><tr><td data-rotulo=\"Quando\">Depois de cada ocorrência</td><td data-rotulo=\"Ação de formação\">Reunião de avaliação: o que funcionou e o que mudar.</td></tr><tr><td data-rotulo=\"Quando\">Ao longo do ano</td><td data-rotulo=\"Ação de formação\">Estudo dos guias de proteção do aluno e de sala de aula, família e território.</td></tr></tbody></table></div><h3>Cuidar de quem trabalha</h3><ul><li>Reunir a equipe no mesmo dia de uma ocorrência, para ouvir.</li><li>Permitir que cada um fale do que sentiu, sem obrigar.</li><li>Reconhecer o que a equipe fez bem.</li><li>Encaminhar ao serviço de saúde do servidor quem apresentar sofrimento persistente.</li><li>Distribuir as tarefas mais pesadas, para que não recaiam sempre nas mesmas pessoas.</li><li>Levar à Secretaria as necessidades de apoio psicológico e de segurança.</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Sinais de desgaste na equipe</th><th>O que a direção pode fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Sinais de desgaste na equipe\">Irritação, choro, isolamento</td><td data-rotulo=\"O que a direção pode fazer\">Conversa individual e reservada.</td></tr><tr><td data-rotulo=\"Sinais de desgaste na equipe\">Faltas e atrasos que aumentam</td><td data-rotulo=\"O que a direção pode fazer\">Perguntar do que a pessoa precisa antes de cobrar.</td></tr><tr><td data-rotulo=\"Sinais de desgaste na equipe\">Medo de vir trabalhar</td><td data-rotulo=\"O que a direção pode fazer\">Levar à Secretaria. Rever trajeto e horário, se possível.</td></tr><tr><td data-rotulo=\"Sinais de desgaste na equipe\">Indiferença: \"nada adianta\"</td><td data-rotulo=\"O que a direção pode fazer\">Mostrar resultados concretos. Dividir decisões.</td></tr></tbody></table></div><div class=\"nota\"><b>A direção também precisa de apoio</b><br/>Quem decide na crise carrega um peso grande. Mantenha contato com outros diretores, peça apoio à Secretaria e cuide da sua saúde.</div>"},{"id":"c25","titulo":"Registrar e aprender com cada ocorrência","html":"<p>O registro protege a escola, orienta a Secretaria e permite melhorar o plano. Ele descreve fatos e decisões, sem identificar pessoas do território.</p><div class=\"rapido\"><p><b>Escola:</b> ____________________ <b>Data:</b> ____/____/______ <b>Turno:</b> __________</p><p><b>O que ocorreu (fatos, horário de início e de fim):</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Nível de alerta adotado e quem decidiu:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Medidas tomadas:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Pessoas feridas ou que precisaram de atendimento:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Comunicações feitas (Secretaria, 190, 192, responsáveis) e horários:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Aulas afetadas:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>O que funcionou e o que precisa mudar no plano:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Indicador</th><th>Para que serve</th></tr></thead><tbody><tr><td data-rotulo=\"Indicador\">Dias e turnos com aulas interrompidas</td><td data-rotulo=\"Para que serve\">Planejar a reposição e mostrar à rede o impacto.</td></tr><tr><td data-rotulo=\"Indicador\">Frequência nos dias seguintes a ocorrências</td><td data-rotulo=\"Para que serve\">Identificar alunos que não voltaram.</td></tr><tr><td data-rotulo=\"Indicador\">Alunos em busca ativa e retornos</td><td data-rotulo=\"Para que serve\">Acompanhar o risco de abandono.</td></tr><tr><td data-rotulo=\"Indicador\">Servidores afastados</td><td data-rotulo=\"Para que serve\">Dimensionar o apoio à equipe.</td></tr><tr><td data-rotulo=\"Indicador\">Tempo para todos chegarem ao local mais seguro, nos treinos</td><td data-rotulo=\"Para que serve\">Melhorar o procedimento.</td></tr></tbody></table></div><div class=\"nota\"><b>Registro reservado</b><br/>Os registros ficam com a direção e seguem para a Secretaria pelo canal oficial. Não são compartilhados em grupos de mensagens.</div>"},{"id":"c26","titulo":"Mais casos para estudo","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · o recado na porta</div><p><b>Situação.</b> No início da manhã, um homem diz ao porteiro que \"é melhor a escola não funcionar à tarde\".</p><p><b>O que fazer.</b></p><ol><li>O porteiro não discute e avisa a direção.</li><li>A direção comunica à Secretaria no mesmo momento.</li><li>A escola passa ao nível de atenção: sem atividades externas, portões controlados.</li><li>A Secretaria decide sobre o turno da tarde e a direção informa os responsáveis pelo canal oficial.</li><li>O contato é registrado, sem identificar a pessoa.</li></ol><p><b>Resultado esperado.</b> A decisão é tomada pela rede, e nenhum servidor fica exposto.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · os alunos que pararam de vir</div><p><b>Situação.</b> Depois de um confronto no bairro, onze alunos de uma mesma localidade faltam por uma semana.</p><p><b>O que fazer.</b></p><ol><li>A direção entende o motivo com parceiros do território, sem cobrar presença.</li><li>A escola faz contato de acolhimento com as famílias.</li><li>A Secretaria é informada e avalia o transporte e o trajeto.</li><li>Os professores preparam atividades para recuperar o que foi perdido.</li><li>Na volta, os alunos são recebidos sem perguntas diante da turma.</li></ol><p><b>Resultado esperado.</b> Os alunos retornam aos poucos, e a escola identifica dois que precisam de acompanhamento da rede.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a mãe que queria tirar o filho da turma</div><p><b>Situação.</b> Uma mãe exige a mudança de turma do filho porque ele estuda com o filho de uma família com quem ela tem conflito no bairro.</p><p><b>O que fazer.</b></p><ol><li>A direção ouve em particular e não comenta o conflito.</li><li>Avalia se há risco para os alunos dentro da escola.</li><li>Explica que a escola trata todos os alunos da mesma forma.</li><li>Se houver risco real, decide a medida com a Secretaria, com discrição e sem expor nenhuma das famílias.</li><li>Os professores observam a convivência entre os dois alunos.</li></ol><p><b>Resultado esperado.</b> A escola protege os dois alunos e não entra na disputa.</p></div>"},{"id":"c27","titulo":"Roteiro de estudo em grupo","html":"<p>Este guia rende mais quando é estudado com colegas. O roteiro abaixo divide a leitura em encontros de uma hora, que podem acontecer nas reuniões pedagógicas ou em grupos de estudo. Cada pessoa lê os capítulos antes do encontro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Encontro</th><th>Capítulos</th><th>Perguntas para a conversa</th></tr></thead><tbody><tr><td data-rotulo=\"Encontro\">1</td><td data-rotulo=\"Capítulos\">Do início até \"A rede de proteção\"</td><td data-rotulo=\"Perguntas para a conversa\">Que conflitos com famílias são mais frequentes? Conhecemos os nossos parceiros na rede?</td></tr><tr><td data-rotulo=\"Encontro\">2</td><td data-rotulo=\"Capítulos\">De \"Quando o território afeta a rotina\" até \"O plano de segurança\"</td><td data-rotulo=\"Perguntas para a conversa\">O nosso plano está escrito? Todos conhecem os locais mais seguros?</td></tr><tr><td data-rotulo=\"Encontro\">3</td><td data-rotulo=\"Capítulos\">De \"Comunicação durante a crise\" até \"Relação com as forças de segurança\"</td><td data-rotulo=\"Perguntas para a conversa\">Quem fala com os responsáveis em uma ocorrência? Como tratamos pressões externas?</td></tr><tr><td data-rotulo=\"Encontro\">4</td><td data-rotulo=\"Capítulos\">De \"Como a violência afeta a aprendizagem\" até \"Alunos em risco de abandonar\"</td><td data-rotulo=\"Perguntas para a conversa\">Como acolhemos alunos em luto? A nossa busca ativa funciona?</td></tr><tr><td data-rotulo=\"Encontro\">5</td><td data-rotulo=\"Capítulos\">De \"Boatos\" até o final</td><td data-rotulo=\"Perguntas para a conversa\">Como cuidamos da equipe? O que vamos rever no plano?</td></tr></tbody></table></div><h3>Como conduzir cada encontro</h3><ol class=\"passos\"><li>Rodada inicial: cada um diz, em uma frase, o que mais chamou a atenção na leitura.</li><li>Discussão das perguntas, primeiro em duplas e depois no grupo.</li><li>Análise de um dos casos do guia ou de uma situação da escola, sem citar nomes.</li><li>Combinado: o que cada um vai experimentar até o próximo encontro.</li><li>No encontro seguinte, a conversa começa pelo relato do que foi experimentado.</li></ol><div class=\"nota\"><b>Registro</b><br/>As anotações sobre o território e sobre o plano de segurança são reservadas e ficam com a direção.</div>"},{"id":"c28","titulo":"Referências","html":"<ul><li>Estatuto da Criança e do Adolescente (Lei nº 8.069/1990), arts. 13, 56 e 245.</li><li>Lei nº 13.431/2017, sobre a escuta de crianças e adolescentes vítimas ou testemunhas de violência.</li><li>Lei nº 14.643/2023, que autoriza o Sistema Nacional de Acompanhamento e Combate à Violência nas Escolas.</li><li>Lei nº 13.935/2019, sobre serviços de psicologia e de serviço social nas redes públicas de educação básica.</li><li>Comitê Internacional da Cruz Vermelha: metodologia Acesso Mais Seguro para Serviços Públicos Essenciais e guia de Comportamentos Mais Seguros para profissionais da educação.</li><li>Ministério da Educação: programa Escola que Protege.</li></ul>"},{"id":"c29","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> Durante disparos no entorno, a direção deve:</p><ol type=\"a\"><li>Manter os alunos na escola, em local mais seguro.</li><li>Mandar olhar pela janela para avaliar.</li><li>Ligar para os responsáveis virem buscar.</li><li>Liberar os alunos rapidamente.</li></ol></div><div class=\"qz\"><p><b>2.</b> Um grupo armado pede que a escola feche mais cedo. A direção deve:</p><ol type=\"a\"><li>Recusar e enfrentar.</li><li>Comunicar imediatamente à Secretaria, sem negociar sozinha.</li><li>Avisar os alunos em sala.</li><li>Negociar um horário.</li></ol></div><div class=\"qz\"><p><b>3.</b> Diante da suspeita de maus-tratos contra um aluno, a escola:</p><ol type=\"a\"><li>Conversa com o suposto agressor.</li><li>Investiga até ter certeza.</li><li>Comunica ao Conselho Tutelar.</li><li>Aguarda a família procurar.</li></ol></div><div class=\"qz\"><p><b>4.</b> Não se faz mediação quando:</p><ol type=\"a\"><li>Os dois alunos aceitam conversar.</li><li>O conflito é antigo.</li><li>Há uma discussão entre colegas.</li><li>Uma das partes tem medo da outra ou houve violência grave.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> a) Manter os alunos na escola, em local mais seguro. Enquanto há risco, a escola é mais segura do que a rua.</p><p><b>2.</b> b) Comunicar imediatamente à Secretaria, sem negociar sozinha. A escola não negocia nem confronta.</p><p><b>3.</b> c) Comunica ao Conselho Tutelar. A comunicação da suspeita é obrigatória.</p><p><b>4.</b> d) Uma das partes tem medo da outra ou houve violência grave. Nesses casos, a escola protege a vítima.</p></div>"},{"id":"c30","titulo":"Glossário","html":"<dl><dt>Aliciamento</dt><dd>Aproximação gradual de um adulto ou de um grupo para explorar uma criança ou um adolescente.</dd><dt>Busca ativa</dt><dd>Ação da escola e da rede para localizar e trazer de volta o aluno que deixou de frequentar.</dd><dt>CAPS</dt><dd>Centro de Atenção Psicossocial. Atende sofrimento psíquico intenso e uso de substâncias.</dd><dt>Comportamento mais seguro</dt><dd>Conjunto de condutas que reduzem o risco durante situações de violência armada.</dd><dt>Conselho Tutelar</dt><dd>Órgão que zela pelos direitos de crianças e adolescentes.</dd><dt>CRAS</dt><dd>Centro de Referência de Assistência Social. Atende famílias em vulnerabilidade.</dd><dt>CREAS</dt><dd>Centro de Referência Especializado de Assistência Social. Atende situações de violação de direitos.</dd><dt>Estado de alerta</dt><dd>Condição em que o corpo se mantém preparado para o perigo, o que prejudica a atenção e a memória.</dd><dt>Local mais seguro</dt><dd>Espaço da escola mais protegido de disparos, definido no plano de segurança.</dd><dt>Neutralidade</dt><dd>Princípio pelo qual a escola atende a todos e não toma partido em disputas do território.</dd><dt>Nível de alerta</dt><dd>Grau de risco definido pela direção, com ações combinadas para cada um.</dd><dt>Plano de segurança</dt><dd>Documento que define responsáveis, sinais, locais e procedimentos da escola em situações de risco.</dd><dt>Rede de proteção</dt><dd>Conjunto de serviços que garantem os direitos de crianças e adolescentes.</dd><dt>Território</dt><dd>O bairro e o entorno onde a escola está, com as suas relações e os seus riscos.</dd></dl>"}];

/** Avaliação final do livro. O gabarito só é usado no servidor. */
export const avaliacao: QuestaoDaAvaliacao[] = [{"pergunta":"O mapa do território da escola deve ser:","alternativas":["Reservado à direção, sem nomes de pessoas.","Enviado ao grupo dos responsáveis.","Dispensável.","Afixado no mural."],"correta":0,"explicacao":"É informação sensível."},{"pergunta":"No nível de alerta, com ocorrência no entorno, os alunos:","alternativas":["Vão para o pátio.","Aguardam no portão.","São liberados para casa.","Permanecem dentro dos prédios, longe de áreas expostas."],"correta":3,"explicacao":"A escola é mais segura do que a rua."},{"pergunta":"Um recado para fechar a escola deve ser:","alternativas":["Ignorado.","Atendido de imediato.","Comunicado à Secretaria, que decide.","Discutido com o portador."],"correta":2,"explicacao":"Nenhum gestor decide ou negocia sozinho."},{"pergunta":"Durante uma ocorrência, a mensagem aos responsáveis diz que:","alternativas":["Venham buscar os alunos.","Os alunos estão protegidos e que não venham agora.","A escola não sabe o que fazer.","Há detalhes do confronto."],"correta":1,"explicacao":"Mensagem curta e verdadeira."},{"pergunta":"Diante de um aluno aliciado por grupo criminoso, a escola:","alternativas":["Mantém o vínculo e aciona a rede de proteção.","Investiga.","Avisa os colegas.","Expulsa."],"correta":0,"explicacao":"O adolescente é vítima de exploração."},{"pergunta":"Uma arma encontrada na escola deve ser:","alternativas":["Entregue ao aluno.","Guardada na direção.","Isolada, sem toque, com acionamento do 190.","Fotografada para os grupos."],"correta":2,"explicacao":"Ninguém manuseia."},{"pergunta":"Pedido de dados de alunos por autoridade deve ser:","alternativas":["Atendido verbalmente.","Solicitado por escrito e encaminhado à Secretaria.","Negado sempre.","Publicado."],"correta":1,"explicacao":"Dados são protegidos por lei."},{"pergunta":"Depois de uma ocorrência, a direção deve:","alternativas":["Punir quem errou.","Fechar a escola por uma semana.","Evitar o assunto.","Reunir a equipe, acolher, registrar e rever o plano."],"correta":3,"explicacao":"Cada ocorrência melhora o plano."}];
